	switch s.reg.release(service, instance, r.Header.Get(LeaseHeader)) {
	case leaseOK:
		w.WriteHeader(http.StatusNoContent)
	case leaseNotFound:
		writeError(w, http.StatusNotFound, "instance_not_found")
