// decodeRegistration strictly decodes one JSON object from the request body.
// Any malformed, trailing, oversized or wrongly typed payload is rejected as
// a validation error.
func decodeRegistration(w http.ResponseWriter, r *http.Request, req *registrationRequest) bool {
	r.Body = http.MaxBytesReader(w, r.Body, maxRegistrationBody)
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(req); err != nil {
		return false
	}
	// Reject trailing data after the JSON object.
	var extra json.RawMessage
	if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
		return false
	}
	return true
}

