1	package server
2	
3	import (
4		"crypto/rand"
5		"encoding/hex"
6		"sort"
7		"sync"
8		"time"
9	)
10	
11	// Instance is the public view of a registered service instance.
12	type Instance struct {
13		Instance   string            `json:"instance"`
14		Endpoint   string            `json:"endpoint"`
15		Version    string            `json:"version"`
16		Zone       string            `json:"zone"`
17		Weight     int               `json:"weight"`
18		TTLSeconds int               `json:"ttlSeconds"`
19		Metadata   map[string]string `json:"metadata,omitempty"`
20		ExpiresAt  time.Time         `json:"expiresAt"`
21	}
22	
23	// registration is the live, mutable record held by the registry.
24	type registration struct {
25		service    string
26		instance   string
27		endpoint   string
28		version    string
29		zone       string
30		weight     int
31		ttl        time.Duration
32		metadata   map[string]string
33		leaseToken string
34		expiresAt  time.Time
35	}
36	
37	// expiredLocked reports whether the record is past its lease deadline.
38	// Callers must hold mu.
39	func (r *registration) expiredLocked(now time.Time) bool {
40		return !now.Before(r.expiresAt)
41	}
42	
43	// snapshotLocked builds the immutable public view returned to clients.
44	// Callers must hold mu.
45	func (r *registration) snapshotLocked() Instance {
46		var meta map[string]string
47		if len(r.metadata) > 0 {
48			meta = make(map[string]string, len(r.metadata))
49			for k, v := range r.metadata {
50				meta[k] = v
51			}
52		}
53		return Instance{
54			Instance:   r.instance,
55			Endpoint:   r.endpoint,
56			Version:    r.version,
57			Zone:       r.zone,
58			Weight:     r.weight,
59			TTLSeconds: int(r.ttl / time.Second),
60			Metadata:   meta,
61			ExpiresAt:  r.expiresAt,
62		}
63	}
64	
65	// registry is the in-process, in-memory store of service instances. It is
66	// empty on every process start. A single mutex guards every read and write,
67	// and expiry plus token checks happen while the lock is held, so a stale
68	// token from a superseded or released lease can never extend or resurrect a
69	// registration.
70	type registry struct {
71		mu      sync.Mutex
72		records map[string]*registration
73		now     func() time.Time
74	}
75	
76	func newRegistry() *registry {
77		return &registry{
78			records: make(map[string]*registration),
79			now:     time.Now,
80		}
81	}
82	
83	func regKey(service, instance string) string {
84		return service + "/" + instance
85	}
86	
87	func newLeaseToken() (string, error) {
88		var b [32]byte
89		if _, err := rand.Read(b[:]); err != nil {
90			return "", err
91		}
92		return hex.EncodeToString(b[:]), nil
93	}
94	
95	// register inserts or supersedes a registration. A fresh lease token is
96	// issued on every call, so any token held for a previous registration of the
97	// same key stops working immediately. It returns the new token, the public
98	// snapshot and whether a still-live registration was overwritten.
99	func (reg *registry) register(service, instance, endpoint, version, zone string, weight int, ttl time.Duration, metadata map[string]string) (string, Instance, bool, error) {
100		token, err := newLeaseToken()
101		if err != nil {
102			return "", Instance{}, false, err
103		}
104	
105		meta := make(map[string]string, len(metadata))
106		for k, v := range metadata {
107			meta[k] = v
108		}
109	
110		reg.mu.Lock()
111		defer reg.mu.Unlock()
112		now := reg.now()
113		key := regKey(service, instance)
114		_, overwritten := reg.lookupLocked(key, now)
115		rec := &registration{
116			service:    service,
117			instance:   instance,
118			endpoint:   endpoint,
119			version:    version,
120			zone:       zone,
121			weight:     weight,
122			ttl:        ttl,
123			metadata:   meta,
124			leaseToken: token,
125			expiresAt:  now.Add(ttl),
126		}
127		reg.records[key] = rec
128		return token, rec.snapshotLocked(), overwritten, nil
129	}
130	
131	type leaseResult int
132	
133	const (
134		leaseOK leaseResult = iota
135		leaseNotFound
136		leaseConflict
137	)
138	
139	// lookupLocked returns the live record for the key, deleting and reporting
140	// absent when the registration is missing or expired. Callers must hold mu.
141	func (reg *registry) lookupLocked(key string, now time.Time) (*registration, bool) {
142		rec, ok := reg.records[key]
143		if !ok {
144			return nil, false
145		}
146		if rec.expiredLocked(now) {
147			delete(reg.records, key)
148			return nil, false
149		}
150		return rec, true
151	}
152	
153	func checkLease(rec *registration, token string) leaseResult {
154		if token == "" || token != rec.leaseToken {
155			return leaseConflict
156		}
157		return leaseOK
158	}
159	
160	// renew extends the lease of a live instance whose token matches. The new
161	// deadline is computed from the moment the request is accepted.
162	func (reg *registry) renew(service, instance, token string) (Instance, leaseResult) {
163		reg.mu.Lock()
164		defer reg.mu.Unlock()
165		now := reg.now()
166		rec, ok := reg.lookupLocked(regKey(service, instance), now)
167		if !ok {
168			return Instance{}, leaseNotFound
169		}
170		if result := checkLease(rec, token); result != leaseOK {
171			return Instance{}, result
172		}
173		rec.expiresAt = now.Add(rec.ttl)
174		return rec.snapshotLocked(), leaseOK
175	}
176	
177	// release removes a live instance whose token matches.
178	func (reg *registry) release(service, instance, token string) leaseResult {
179		reg.mu.Lock()
180		defer reg.mu.Unlock()
181		key := regKey(service, instance)
182		rec, ok := reg.lookupLocked(key, reg.now())
183		if !ok {
184			return leaseNotFound
185		}
186		if result := checkLease(rec, token); result != leaseOK {
187			return result
188		}
189		delete(reg.records, key)
190		return leaseOK
191	}
192	
193	// snapshot returns the current live instances of a service sorted by
194	// instance name, optionally filtered by exact version and zone. Expired
195	// records encountered during the scan are pruned and never returned.
196	func (reg *registry) snapshot(service, version, zone string) []Instance {
197		reg.mu.Lock()
198		defer reg.mu.Unlock()
199		now := reg.now()
200		out := make([]Instance, 0)
201		for key, rec := range reg.records {
202			if rec.service != service {
203				continue
204			}
205			if rec.expiredLocked(now) {
206				delete(reg.records, key)
207				continue
208			}
209			if version != "" && rec.version != version {
210				continue
211			}
